  [
    {
      "fieldName": "ucinn_ascendv2__Adjustment_Reason_v1__c",
      "objectApiName": "Opportunity",
      "important": false,
      "required": true,
      "changeLayout": true,
      "customFieldParams": {
        "type": "multiselectpicklist",
        "customPicklistExclusions": [
          "Void",
          "Terminated",
          "Written Off",
          "Cancelled"
        ]
      },
      "criteria": [
        {
          "isAdjustment": true,
          "isView": false
