    {
      "fieldName": "ucinn_ascendv2__Adjustment_Reason_Other__c",
      "objectApiName": "Opportunity",
      "important": false,
      "required": true,
      "criteria": [
        {
          "isAdjustment": true,
          "isView": false,
          "transactionRecords.TransactionInformation.Opportunity.ucinn_ascendv2__Adjustment_Reason_v1__c": "$includes('Other')"
        }
      ]
    }
  ]
